function voiceSupported(){return Boolean(navigator.mediaDevices?.getUserMedia&&window.RTCPeerConnection)}
function updateMicButton(){const b=$('micBtn');if(!b)return;b.classList.toggle('voice-on',voiceOn);b.classList.toggle('voice-speaking',voiceOn&&voiceSpeaking);b.setAttribute('aria-label',voiceOn?'Mute microphone':'Turn microphone on');b.title=voiceOn?(voiceSpeaking?'Microphone on — you are speaking':'Microphone on — tap to mute'):'Microphone off';if(!voiceSupported()){b.disabled=true;b.title='Voice chat is not supported on this device'}}
async function voicePost(path,data={}){const response=await fetch('/api/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({room,playerId:myId,...data}),cache:'no-store'});const json=await response.json();if(!json.ok)throw new Error(json.error||'Voice chat error');return json}
function voiceStatus(enabled,speaking=false){if(!room||!myId)return Promise.resolve();return voicePost('voice-status',{enabled:Boolean(enabled),speaking:Boolean(enabled&&speaking)}).catch(()=>{})}
function closeVoicePeer(peerId){const entry=voicePeers.get(peerId);if(!entry)return;voicePeers.delete(peerId);entry.closing=true;try{entry.pc.onconnectionstatechange=null;entry.pc.onicecandidate=null;entry.pc.ontrack=null;entry.pc.close()}catch{}try{entry.audio.pause();entry.audio.srcObject=null;entry.audio.remove()}catch{}}
function closeAllVoicePeers(){for(const peerId of [...voicePeers.keys()])closeVoicePeer(peerId)}
async function sendVoiceSignal(targetId,signal){try{await voicePost('voice-signal',{targetId,signal})}catch(e){if(voiceOn&&String(e.message||'').includes('enable voice'))return}}
function serialDescription(description){return description?.toJSON?description.toJSON():description}
function serialCandidate(candidate){return candidate?.toJSON?candidate.toJSON():candidate}
function makeVoicePeer(peerId){if(voicePeers.has(peerId))return voicePeers.get(peerId);const pc=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'},{urls:'stun:stun1.l.google.com:19302'}]});const audio=document.createElement('audio');audio.autoplay=true;audio.playsInline=true;audio.dataset.voicePeer=peerId;$('voiceAudioRack')?.appendChild(audio);const entry={pc,audio,pendingCandidates:[],offerStarted:false,closing:false};voicePeers.set(peerId,entry);for(const track of (localVoiceStream?.getTracks()||[]))pc.addTrack(track,localVoiceStream);pc.onicecandidate=event=>{if(event.candidate&&voiceOn)sendVoiceSignal(peerId,{type:'candidate',candidate:serialCandidate(event.candidate)})};pc.ontrack=event=>{const stream=event.streams?.[0]||new MediaStream([event.track]);audio.srcObject=stream;audio.play().catch(()=>{})};pc.onconnectionstatechange=()=>{if(entry.closing)return;if(pc.connectionState==='failed'||pc.connectionState==='closed'){closeVoicePeer(peerId);setTimeout(()=>{const remote=state?.players?.find(p=>p.id===peerId);if(voiceOn&&remote?.voiceEnabled&&remote?.connected)ensureVoicePeer(peerId)},900)}};return entry}
