async function pollVoiceSignals(){if(!voiceOn||!room||!myId)return;try{const q=new URLSearchParams({room,playerId:myId});const response=await fetch('/api/voice-signals?'+q.toString(),{cache:'no-store'});const json=await response.json();if(json.ok)for(const message of (json.signals||[]))await handleVoiceSignal(message)}catch{}}
function startVoiceSignalPolling(){clearInterval(voiceSignalTimer);pollVoiceSignals();voiceSignalTimer=setInterval(pollVoiceSignals,320)}
