async function enableVoice(){if(voiceOn)return;if(!voiceSupported()){toast('Voice chat is not supported on this device');return}try{const stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true},video:false});localVoiceStream=stream;voiceOn=true;voiceSpeaking=false;updateMicButton();startVoiceMonitor(stream);await voiceStatus(true,false);startVoiceSignalPolling();try{const result=await api('state');syncVoicePeers(result.state)}catch{}toast('Microphone on — voice chat ready');haptic(12)}catch(e){voiceOn=false;updateMicButton();const denied=e?.name==='NotAllowedError'||e?.name==='SecurityError';toast(denied?'Microphone permission was not allowed':'Could not start microphone')}}
