function updateAvatarEmotions(previous,next){if(!previous)return;const newAction=next.actionCardVisual&&`${next.actionCardVisual.id}|${next.actionCardVisual.stage}`!==`${previous.actionCardVisual?.id||''}|${previous.actionCardVisual?.stage||''}`,newFlipThree=next.flipThreeVisual&&`${next.flipThreeVisual.id}|${next.flipThreeVisual.stage}`!==`${previous.flipThreeVisual?.id||''}|${previous.flipThreeVisual?.stage||''}`;if(newAction&&next.actionCardVisual.targetId)setAvatarEmotion(next.actionCardVisual.targetId,'shocked',1400);if(newFlipThree&&next.flipThreeVisual.targetId)setAvatarEmotion(next.flipThreeVisual.targetId,'shocked',1400);for(const player of (next.players||[])){const old=previous.players?.find(item=>item.id===player.id);if(!old)continue;const bad=(player.busted&&!old.busted)||(player.frozen&&!old.frozen);const rescued=old.second&&!player.second&&!player.busted;const good=(next.phase==='gameOver'&&previous.phase!=='gameOver'&&next.winner===player.name)||(player.score>old.score)||(player.stayed&&!old.stayed)||(player.second&&!old.second)||(player.cards.length>old.cards.length)||(player.mods.length>old.mods.length)||rescued;if(bad)setAvatarEmotion(player.id,'angry',1900);else if(good)setAvatarEmotion(player.id,'excited',1600)}}
