function cardEl(card,index=0,animate=true){const e=document.createElement('div');e.className='card';e.style.animationDelay=`${Math.min(index*25,160)}ms`;if(!animate)e.style.animation='none';if(card.type==='number'){e.textContent=card.value;e.dataset.label=card.value;e.classList.add('number',`n${card.value}`)}else if(card.type==='modifier'){e.textContent='+'+card.value;e.classList.add('mod');e.dataset.label='BONUS'}else if(card.type==='multiplier'){e.textContent='×2';e.classList.add('mult');e.dataset.label='BOOST'}else{e.textContent=actionName(card.name);e.classList.add('action',card.name);e.dataset.label='ACTION'}return e}
function renderDiscardPile(s){const root=$('discardVisual');if(!root)return;$('discardCount').textContent=s.discardCount||0;root.innerHTML='';if(s.discardTop)root.appendChild(cardEl(s.discardTop,0,false));else root.innerHTML='<div class="discard-empty">DISCARD</div>'}
function flipThreeAnchor(playerId){if(playerId===myId)return $('myArea');const table=$('botTable');if(table)for(const seat of table.children)if(seat.dataset.playerId===playerId)return seat;const strip=$('players');if(strip)for(const player of strip.children)if(player.dataset.playerId===playerId)return player;return $('table')}
