function syncFlipThreeTransfer(s){const visual=s.flipThreeVisual;let card=$('flipThreeTransferCard');if(!visual){if(card&&!card.classList.contains('discarding')){flipThreeTransferId='';flipThreeTransferStage='';card.classList.add('discarding');placeFlipThreeCard(card,$('discardVisual'));setTimeout(()=>card.remove(),520)}return}const stage=visual.stage||'giver',anchorId=stage==='giver'?visual.fromId:visual.targetId;if(!card||flipThreeTransferId!==visual.id){card?.remove();card=cardEl({type:'action',name:'flip3'},0,false);card.id='flipThreeTransferCard';card.classList.add('flip-three-transfer-card');document.body.appendChild(card);flipThreeTransferId=visual.id;flipThreeTransferStage=stage;placeFlipThreeCard(card,flipThreeAnchor(anchorId));tone(590,.1,'triangle');return}if(stage!==flipThreeTransferStage){flipThreeTransferStage=stage;card.classList.add('moving');requestAnimationFrame(()=>placeFlipThreeCard(card,flipThreeAnchor(anchorId)));setTimeout(()=>card.classList.remove('moving'),680);if(visual.targetId===myId){haptic(24);tone(760,.16,'triangle');showLocalScreenEffect('flip3')}}else placeFlipThreeCard(card,flipThreeAnchor(anchorId))}
