function detectSecondChanceVisual(previous,s){if(!previous)return;for(const p of (s.players||[])){const old=previous.players?.find(x=>x.id===p.id);if(!old?.second||p.second)continue;const prefix=`${p.name}'s Second Chance blocked a duplicate `;let value=null;for(let i=(s.log||[]).length-1;i>=0&&i>=(s.log||[]).length-8;i--){const line=s.log[i]||'';if(line.startsWith(prefix)){const m=line.match(/duplicate (\d+)/);if(m)value=Number(m[1]);break}}if(value===null)continue;const token=`${s.round}|${p.id}|${s.log.length}|${value}`;secondChanceVisuals.set(p.id,{value,until:Date.now()+SECOND_CHANCE_REVEAL_MS,token});setTimeout(()=>{const current=secondChanceVisuals.get(p.id);if(current?.token!==token)return;secondChanceVisuals.delete(p.id);lastOpponentTableSig='';if(state)render(state)},SECOND_CHANCE_REVEAL_MS+20)}}
