function fitHandRow(row,reservePreview=false,maxScale=1){if(!row)return;const cards=[...row.children],count=cards.length;if(!count){row.style.removeProperty('--hand-scale');return}const preview=$('scorePreview'),rr=row.getBoundingClientRect(),pr=preview?.getBoundingClientRect(),reserve=reservePreview&&pr?Math.max(0,rr.right-pr.left+6):0,available=Math.max(1,row.clientWidth-16-reserve),baseWidth=window.matchMedia('(min-width:700px)').matches?84:72,stepRatio=.78,baseSpan=baseWidth*(1+(count-1)*stepRatio),scale=Math.min(maxScale,1,available/baseSpan);row.style.setProperty('--hand-scale',String(scale))}
