function renderHand(container,newPlayer,oldPlayer,newState=state,oldState=null){const fresh=visibleCards(newPlayer,newState),prior=visibleCards(oldPlayer,oldState),nextSig=fresh.map(cardKey).join('|'),currentSig=container.dataset.handSig||'';if(currentSig!==nextSig){const animate=oldPlayer?newCardFlags(prior,fresh):fresh.map(()=>false),other=document.createElement('div'),numbers=document.createElement('div');other.className='player-hand-row hand-other';numbers.className='player-hand-row hand-numbers';fresh.forEach((c,i)=>(c.type==='number'?numbers:other).appendChild(cardEl(c,i,animate[i])));container.innerHTML='';container.append(other,numbers);container.dataset.handSig=nextSig}ensureScorePreview(container);const result=newPlayer.busted?{cls:'bust',text:'BUST'}:newPlayer.frozen?{cls:'frozen',text:'FROZEN'}:newPlayer.stayed?{cls:'hold',text:'HOLD'}:null;container.classList.toggle('has-result',Boolean(result));let overlay=container.querySelector('.result-overlay');if(result){if(!overlay){overlay=document.createElement('div');container.appendChild(overlay)}overlay.className=`result-overlay ${result.cls}`;overlay.textContent=result.text}else if(overlay)overlay.remove();fitPlayerHand(container)}
