function renderOpponentTable(s,previous){const table=$('botTable');if(!table)return;const sig=opponentDisplaySignature(s);if(sig===lastOpponentTableSig)return;lastOpponentTableSig=sig;const previousById=new Map((previous?.players||[]).map(p=>[p.id,p]));const turnId=s.phase==='playing'&&!s.pendingAction?s.players[s.turnIndex]?.id:null;table.innerHTML='';s.players.filter(p=>p.id!==myId).forEach(p=>{const old=previousById.get(p.id);const seat=document.createElement('div');seat.dataset.playerId=p.id;seat.className=`bot-seat ${p.id===turnId?'turn':''} ${p.busted?'busted':''} ${p.stayed?'banked':''} ${p.frozen?'frozen':''} ${(p.busted||p.stayed||p.frozen)?'has-result':''} ${p.voiceEnabled?'voice-on':''} ${p.voiceSpeaking?'voice-speaking':''}`.trim();const head=document.createElement('div');head.className='bot-seat-head';const identity=document.createElement('div');identity.className='seat-identity';identity.innerHTML=`<div class="seat-avatar">${avatarPortraitMarkup(p,turnId)}</div><b>${esc(p.name)}${p.computer?' 🤖':''}</b>`;const status=document.createElement('small');status.textContent=p.busted?'BUST':p.frozen?'FROZEN':p.cards.length>=7?'7-CARD +15':p.stayed?'HOLD':`${calculatePreview(p)} pts`;head.append(identity,status);const hand=document.createElement('div');hand.className='bot-hand';const fresh=visibleCards(p,s),prior=visibleCards(old,previous),animate=old?newCardFlags(prior,fresh):fresh.map(()=>false);fresh.forEach((c,i)=>hand.appendChild(cardEl(c,i,animate[i])));seat.append(head,hand);if(p.busted||p.frozen||p.stayed){const overlay=document.createElement('div');overlay.className=`result-overlay ${p.busted?'bust':p.frozen?'frozen':'hold'}`;overlay.textContent=p.busted?'BUST':p.frozen?'FROZEN':'HOLD';seat.appendChild(overlay)}table.appendChild(seat)})}

