function confetti(){const root=$('confetti'),colors=['#32e5cb','#ffdd42','#ff4f8b','#8e7dff','#fff'];root.innerHTML='';for(let i=0;i<70;i++){const x=document.createElement('i');x.className='confetti-piece';x.style.left=Math.random()*100+'%';x.style.background=colors[i%colors.length];x.style.animationDelay=Math.random()*.8+'s';x.style.animationDuration=1.8+Math.random()*1.4+'s';root.appendChild(x)}setTimeout(()=>root.innerHTML='',3500)}
function showSevenBonus(player){const flash=$('bonusFlash');if(!flash||!player)return;flash.innerHTML=`${esc(player.name)} reached 7 number cards!<b>+15</b>`;flash.classList.remove('show');void flash.offsetWidth;flash.classList.add('show');confetti();tone(820,.14,'triangle');setTimeout(()=>tone(1040,.18,'triangle'),120);haptic(22);setTimeout(()=>flash.classList.remove('show'),2200)}
function showWinnerPopup(s){if(!s||s.phase!=='gameOver')return;const standings=[...(s.players||[])].sort((a,b)=>b.score-a.score),winner=standings[0];if(!winner)return;const isHost=s.hostId===myId,rematch=isHost?'<button id="playAgain" class="menu-action play-again" aria-label="Play another game">↻ PLAY AGAIN</button>':'<p style="margin:18px 0 0;color:#8ea4b7">Waiting for the host to play again…</p>';$('closeModal').classList.add('hidden');$('modalBody').innerHTML=`<div style="text-align:center;padding:18px 4px"><div style="font-size:58px">🏆</div><div style="font:900 15px 'Archivo Black';letter-spacing:.18em;color:#32e5cb;margin-top:8px">GAME OVER</div><h2 style="font-size:42px;margin:10px 0;color:#ffdd42">${esc(s.winner||winner.name)} WINS!</h2><p style="font-size:18px;color:white">Final score: <b>${winner.score}</b> points</p><div style="margin:18px 0;padding:14px;border-radius:18px;background:#07111d">${standings.map((p,i)=>`<div style="display:flex;justify-content:space-between;padding:7px 4px;color:${i===0?'#ffdd42':'#dcecff'}"><span>${i+1}. ${esc(p.name)}${p.computer?' 🤖':''}</span><b>${p.score}</b></div>`).join('')}</div>${rematch}</div>`;$('modal').dataset.mode='winner';$('modal').classList.remove('hidden');if(isHost)setTimeout(()=>{const button=$('playAgain');if(button)button.onclick=async()=>{button.disabled=true;button.textContent='STARTING…';try{await api('restart');closeModal()}catch(error){button.disabled=false;button.textContent='↻ PLAY AGAIN';toast(error.message)}}},0);confetti();tone(740,.3);setTimeout(()=>tone(980,.35),180)}
function findNewFlip7(previous,s){if(!previous||!s)return null;for(const p of (s.players||[])){const old=previous.players?.find(x=>x.id===p.id);if((p.cards?.length||0)>=7&&(old?.cards?.length||0)<7)return p}return null}
function latestReactionFor(s,playerId){const reactions=s.reactions||[];for(let i=reactions.length-1;i>=0;i--)if(reactions[i].playerId===playerId)return reactions[i];return null}
function showReaction(reaction,s){if(!reaction||seenReactions.has(reaction.id))return;seenReactions.add(reaction.id);if(seenReactions.size>80){const first=seenReactions.values().next().value;seenReactions.delete(first)}const sender=s.players.find(p=>p.id===reaction.playerId);const pop=$('reactionPop');if(!pop)return;pop.innerHTML=`<span>${esc(reaction.emoji)}</span><div><b>${esc(sender?.name||'Player')}</b><small>SENT A REACTION</small></div>`;pop.classList.remove('show');void pop.offsetWidth;pop.classList.add('show');clearTimeout(reactionTimer);reactionTimer=setTimeout(()=>pop.classList.remove('show'),2600);if(reaction.playerId!==myId){tone(490,.07,'triangle');haptic(10)}}
function renderNewReactions(s){const reactions=s.reactions||[];if(!reactions.length)return;for(const reaction of reactions)showReaction(reaction,s)}
function showPhrase(message,s){if(!message||seenPhrases.has(message.id))return;seenPhrases.add(message.id);if(seenPhrases.size>80){const first=seenPhrases.values().next().value;seenPhrases.delete(first)}const sender=s.players.find(p=>p.id===message.playerId);const pop=$('phrasePop');if(!pop)return;pop.innerHTML=`<b>${esc(sender?.name||'Player')} SAYS</b><strong>${esc(message.phrase)}</strong>`;pop.classList.remove('show');void pop.offsetWidth;pop.classList.add('show');clearTimeout(phraseTimer);phraseTimer=setTimeout(()=>pop.classList.remove('show'),3000);if(message.playerId!==myId){tone(610,.09,'triangle');setTimeout(()=>tone(760,.08,'triangle'),90);haptic(14)}}
function renderNewPhrases(s){for(const message of (s.phrases||[]))showPhrase(message,s)}
function openPhraseTray(){const tray=$('phraseTray'),me=state?.players?.find(p=>p.id===myId);const phrases=[...QUICK_PHRASES];if((me?.name||'').trim().toLowerCase()==='becca')phrases.push(BECCA_PHRASE);tray.innerHTML=phrases.map(phrase=>`<button data-phrase="${esc(phrase)}" class="${phrase===BECCA_PHRASE?'becca-phrase':''}">${esc(phrase)}</button>`).join('');$('reactionTray').classList.add('hidden');tray.classList.toggle('hidden')}
function restoreReactionMenus(){const react=$('react'),reactionTray=$('reactionTray'),phraseTray=$('phraseTray');if(!react||!reactionTray||!phraseTray)return;react.classList.remove('hidden');react.textContent='☺';react.setAttribute('aria-label','Send an emoji or phrase');react.title='Emojis and phrases';reactionTray.innerHTML=REACTION_EMOJIS.map(emoji=>`<button data-emoji="${emoji}" aria-label="Send ${emoji}">${emoji}</button>`).join('')+'<button id="phraseMenuBtn" class="phrase-menu-btn" aria-label="Quick phrases">💬</button>';reactionTray.setAttribute('aria-label','Emojis and phrases');phraseTray.setAttribute('aria-label','Quick phrases')}

function statusText(s,myTurn){if(s.pendingAction){const c=s.players.find(p=>p.id===s.pendingAction.chooserId);if(actionRevealActive(s))return[`${c?.name||'PLAYER'} DREW ${actionName(s.pendingAction.card.name)}`,'Action card revealed'];return[c?.id===myId?`CHOOSE A TARGET FOR ${actionName(s.pendingAction.card.name)}`:`${c?.name} IS CHOOSING A TARGET`,'Action card in play']}if(s.phase==='lobby')return[`WAITING FOR PLAYERS (${s.players.length}/9)`,'Share the room code to invite friends'];if(s.dealing)return['DEALING OPENING CARDS','Cards are being dealt one at a time'];if(s.actionCardVisual){const visual=s.actionCardVisual,giver=s.players.find(p=>p.id===visual.fromId),target=s.players.find(p=>p.id===visual.targetId),label=actionName(visual.name);if(visual.stage==='giver'&&visual.fromId!==visual.targetId)return[`${giver?.name||'PLAYER'} GIVES ${label}`,`Moving to ${target?.name||'the chosen player'}`];if(visual.outcome==='discard')return[`${giver?.name||'PLAYER'} REVEALS ${label}`,'No eligible recipient — moving to discard'];return[`${target?.name||'PLAYER'} RECEIVES ${label}`,visual.name==='freeze'?'Freeze will remain with that player this round':'Protection is being added to that hand']}if(s.flipThreeVisual){const giver=s.players.find(p=>p.id===s.flipThreeVisual.fromId),target=s.players.find(p=>p.id===s.flipThreeVisual.targetId);return s.flipThreeVisual.stage==='giver'?[`${giver?.name||'PLAYER'} GIVES FLIP THREE`,`Moving to ${target?.name||'the chosen player'}`]:[`${target?.name||'PLAYER'} RECEIVES FLIP THREE`,'Three cards are being revealed one at a time']}if(s.resolvingAction)return['ACTION CARD IN PROGRESS','Watch the card move to its recipient'];if(s.phase==='playing')return[myTurn?'YOUR DECISION — FLIP OR HOLD':`${s.players[s.turnIndex]?.name}'S TURN`,myTurn?'How far will you push it?':'Watch the table'];if(s.phase==='roundEnd')return['ROUND COMPLETE','Scores have been banked'];return[`${s.winner} WINS!`,'Game complete']}
function render(s){const previous=state;updateAvatarEmotions(previous,s);state=s;if(s.phase!=='gameOver'&&$('modal').dataset.mode==='winner')closeModal();detectSecondChanceVisual(previous,s);updateActionReveal(s);$('copyCode').querySelector('b').textContent=s.code;$('round').textContent=s.round;$('deckCount').textContent=s.deckCount;renderDiscardPile(s);const me=s.players.find(p=>p.id===myId),oldMe=previous?.players?.find(p=>p.id===myId),frozeNow=Boolean(previous&&me?.frozen&&!oldMe?.frozen),bustedNow=Boolean(previous&&me?.busted&&!oldMe?.busted),turn=s.players[s.turnIndex],turnId=s.phase==='playing'&&!s.pendingAction?turn?.id:'',myTurn=s.phase==='playing'&&!s.dealing&&!s.resolvingAction&&!s.pendingAction&&turn?.id===myId;document.body.classList.toggle('my-turn',myTurn);
$('players').innerHTML='';s.players.forEach((p,i)=>{const e=document.createElement('div');e.className='player '+(s.phase==='playing'&&!s.pendingAction&&i===s.turnIndex?'turn ':'')+(p.voiceEnabled?'voice-on ':'')+(p.voiceSpeaking?'voice-speaking':'');e.dataset.playerId=p.id;const live=p.busted?'BUSTED':p.frozen?`FROZEN ${p.roundScore}`:p.stayed?`BANKED ${p.roundScore}`:`${p.cards.length} NUMBERS`;const reaction=latestReactionFor(s,p.id);e.innerHTML=`<span class="dot ${p.connected?'':'off'}"></span>${reaction?`<div class="player-reaction">${esc(reaction.emoji)}</div>`:''}<div class="name">${esc(p.name)}${p.computer?' 🤖':''}${p.id===s.hostId?' ★':''}${i===s.dealerIndex?' ◇':''}</div><div class="score">${p.score}</div><small>${live}${p.second?' · 2ND CHANCE':''}</small>`;$('players').appendChild(e)});
const area=$('myArea'),localBadge=$('myAvatarBadge');if(me){renderHand(area,me,oldMe,s,previous);if(localBadge)localBadge.innerHTML=avatarPortraitMarkup(me,turnId)}else{area.innerHTML='';area.dataset.handSig='';ensureScorePreview(area);if(localBadge)localBadge.innerHTML=''}renderOpponentTable(s,previous);renderVoiceSeatStates(s);ensureScorePreview(area).querySelector('b').textContent=calculatePreview(me);syncFlipThreeTransfer(s);syncActionCardTransfer(s);
renderTargetPicker(s);$('hit').disabled=!myTurn;$('stay').disabled=!myTurn||!(me&&(me.cards.length||me.mods.length||me.second));$('hit').classList.toggle('hidden',s.phase!=='playing'||!!s.pendingAction);$('stay').classList.toggle('hidden',s.phase!=='playing'||!!s.pendingAction);$('start').classList.toggle('hidden',!(s.phase==='lobby'&&s.hostId===myId));$('next').classList.toggle('hidden',!(s.phase==='roundEnd'&&s.hostId===myId));$('lobbyCard').classList.toggle('hidden',s.phase!=='lobby');$('table').classList.toggle('hidden',s.phase==='lobby');
const [big,small]=statusText(s,myTurn);$('status').innerHTML=`<span class="pulse"></span><b>${esc(big)}</b><small>${esc(small)}</small>`;$('log').innerHTML=s.log.map(x=>`<div>${esc(x)}</div>`).join('');
renderNewReactions(s);renderNewPhrases(s);syncVoicePeers(s);
if(previous){const newCount=(me?.cards.length||0)+(me?.mods.length||0)+(me?.second?1:0),oldCount=(oldMe?.cards.length||0)+(oldMe?.mods.length||0)+(oldMe?.second?1:0);if(newCount>oldCount){tone(680,.08,'triangle');haptic(12)}const flip7Player=findNewFlip7(previous,s);if(flip7Player)showSevenBonus(flip7Player);if(previous.phase!=='gameOver'&&s.phase==='gameOver'){if(flip7Player)setTimeout(()=>showWinnerPopup(s),2300);else showWinnerPopup(s)}}else if(s.phase==='gameOver'){setTimeout(()=>showWinnerPopup(s),120)}if(bustedNow){const showBust=()=>{if(state?.players.find(p=>p.id===myId)?.busted)showLocalScreenEffect('bust')};if(s.flipThreeVisual||previous?.flipThreeVisual)setTimeout(showBust,FLIP3_BUST_DELAY_MS);else showBust()}else if(frozeNow)showLocalScreenEffect('freeze');lastPhase=s.phase}
function showModal(html,mode=''){$('modalBody').innerHTML=html;$('modal').classList.remove('hidden');if(mode==='leave')setTimeout(()=>{const b=$('confirmLeave');if(b)b.onclick=leave},0)}
function closeModal(){$('modal').classList.add('hidden');$('modal').dataset.mode='';$('closeModal').classList.remove('hidden')}
$('closeModal').onclick=closeModal;$('modal').onclick=e=>{if(e.target===$('modal'))closeModal()}
const help=`<h2>How to play</h2><p>Build the highest score without revealing a duplicate number.</p><ol><li>On your turn, choose <b>Flip</b> to draw or <b>Stay</b> to bank your round value.</li><li>A duplicate number busts your round unless a Second Chance protects you. You may hold only one Second Chance; if you draw another, give it to another active player who does not have one, or discard it if nobody can receive it.</li><li>Second Chance protects only against a duplicate Number card. It does not block Freeze.</li><li>Freeze and Flip Three may target any active player, including yourself.</li><li>During Flip Three, all three revealed cards count unless the target busts or reaches Flip 7. A Second Chance resolves immediately; other Action cards wait until the three-card sequence finishes.</li><li>Seven unique Number cards immediately end the round and award a 15-point bonus. ×2 doubles only the Number-card subtotal; additive modifiers and the +15 bonus are added afterward.</li><li>Once the high score is at least 200, the highest total wins. If the highest score is tied, everyone plays another full round.</li><li>In multiplayer, tap the microphone button to join voice chat. It starts muted and only broadcasts after you grant microphone permission and turn it on.</li></ol><button class="menu-action" onclick="document.getElementById('modal').classList.add('hidden')">GOT IT</button>`;
$('howBtn').onclick=()=>showModal(help);$('menuBtn').onclick=()=>showModal(`<h2>Game menu</h2><button class="menu-action" id="menuHow">HOW TO PLAY</button><button class="menu-action" id="menuSound">${soundOn?'MUTE SOUND':'TURN SOUND ON'}</button><button class="menu-action" id="menuLeave">LEAVE ROOM</button>`);$('modalBody').addEventListener('click',e=>{if(e.target.id==='menuHow')showModal(help);if(e.target.id==='menuSound'){soundOn=!soundOn;localStorage.fr7sound=soundOn?'on':'off';toast(soundOn?'Sound on':'Sound muted');closeModal()}if(e.target.id==='menuLeave')leave()});
$('soundBtn').onclick=()=>{soundOn=!soundOn;localStorage.fr7sound=soundOn?'on':'off';$('soundBtn').textContent=soundOn?'♪':'×';if(soundOn)tone(520,.08)};$('soundBtn').textContent=soundOn?'♪':'×';
$('micBtn').onclick=toggleVoice;updateMicButton();window.addEventListener('pagehide',voicePageHide);
restoreReactionMenus();
$('react').onclick=()=>{haptic(8);$('phraseTray').classList.add('hidden');$('reactionTray').classList.toggle('hidden')};$('reactionTray').onclick=e=>{const button=e.target.closest('button');if(!button)return;if(button.id==='phraseMenuBtn'){haptic(8);openPhraseTray();return}const emoji=button.dataset.emoji;if(!emoji)return;$('reactionTray').classList.add('hidden');haptic(8);api('react',{emoji}).then(()=>{toast(`${emoji} sent to everyone`);tone(420,.05)}).catch(err=>toast(err.message))};$('phraseTray').onclick=e=>{const button=e.target.closest('button[data-phrase]');if(!button)return;const phrase=button.dataset.phrase;$('phraseTray').classList.add('hidden');haptic(8);api('phrase',{phrase}).then(()=>{toast('Phrase sent to everyone');tone(520,.06)}).catch(err=>toast(err.message))};
